{"result":[{"event_message":"statement: -- Public @handles for members. Released 18 November.\nalter table public.profiles add column handle text;\nupdate public.profiles set handle = lower(display_name);\nalter table public.profiles alter column handle set not null;\ncreate unique index profiles_handle_key on public.profiles (handle);\ngrant update (handle) on public.profiles to authenticated;\n\n\n-- source: POST /v1/projects/:ref/database/query\n-- user: scoped_pat:4a63888f-eb85-47ee-a771-e2a228c6f266\n-- date: 2026-11-19T09:55:12.716Z","source":"postgres_logs","timestamp":"2026-11-19T09:55:14.257000"},{"event_message":"{\"auth_event\":{\"action\":\"user_signedup\",\"actor_id\":\"00000000-0000-0000-0000-000000000000\",\"actor_username\":\"service_role\",\"actor_via_sso\":false,\"log_type\":\"team\",\"traits\":{\"provider\":\"email\",\"user_email\":\"carol@example.com\",\"user_id\":\"1b71fec5-94b6-4f5d-945a-204843b3cd0c\",\"user_phone\":\"\"}},\"component\":\"api\",\"duration\":86023365,\"level\":\"info\",\"method\":\"POST\",\"msg\":\"request completed\",\"path\":\"/admin/users\",\"referer\":\"http://localhost:3000\",\"remote_addr\":\"178.89.173.234\",\"request_id\":\"01a1f33b-4557-7d21-9009-02eb1f2a54cb\",\"status\":200,\"time\":\"2026-11-19T09:55:10Z\"}","source":"auth_logs","timestamp":"2026-11-19T09:55:10.000000"},{"event_message":"{\"auth_event\":{\"action\":\"user_signedup\",\"actor_id\":\"00000000-0000-0000-0000-000000000000\",\"actor_username\":\"service_role\",\"actor_via_sso\":false,\"log_type\":\"team\",\"traits\":{\"provider\":\"email\",\"user_email\":\"bob@example.com\",\"user_id\":\"0f709486-4c93-4088-80f6-b75a7000b8ae\",\"user_phone\":\"\"}},\"component\":\"api\",\"duration\":84823037,\"level\":\"info\",\"method\":\"POST\",\"msg\":\"request completed\",\"path\":\"/admin/users\",\"referer\":\"http://localhost:3000\",\"remote_addr\":\"178.89.173.234\",\"request_id\":\"01a1f33b-4416-7ef8-a3a6-f6e96652bb93\",\"status\":200,\"time\":\"2026-11-19T09:55:10